mapper.select:
SELECT r.*
FROM registration r
INNER JOIN schedule s ON r.schedule_id = s.id
WHERE r.doctor_id = #{doctorId}
  AND s.work_date = #{workDate}
ORDER BY r.queue_no ASC

SELECT r.* FROM registration r INNER JOIN `user` pu ON r.patient_id = pu.id INNER JOIN `user` du ON r.doctor_id = du.id INNER JOIN department d ON r.department_id = d.id WHERE 1 = 1
AND (LOWER(r.reg_no) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(pu.real_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(du.real_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')))
AND r.status = #{status}
AND r.department_id = #{departmentId}
AND r.doctor_id = #{doctorId}
AND r.paid_at IS NOT NULL
AND r.paid_at IS NULL
AND r.created_at >= #{startTime}
AND r.created_at <= #{endTime}
ORDER BY r.created_at DESC
